/// <summary>
/// PaffH 03.09.25
/// </summary>
/// <param name="sender">FormControl</param>
/// <param name="e">FormControlEventArgs</param>
[FormControlEventHandler(formControlStr(smmContactPerson, NDXFormButtonGetContact), FormControlEventType::Clicked),
    SuppressBPWarning('BPParameterNotUsed', '"e" is not used')]
public static void NDXFormButtonGetContact_OnClicked(FormControl sender, FormControlEventArgs e)
{
    FormRun formrun = sender.formRun();
    FormDataSource fds = formrun.dataHelper().FindDataSource(formDataSourceStr(smmContactPerson, ContactPerson));
    ContactPerson contactPerson = fds.cursor();
    NDXBVEMailRequestControlCenterFormI formHandlerCaller = NDXAVAKBVBuildingProjectSearch_frm_EventHandler::formHandlerCaller(formRun);
    formHandlerCaller.setContactPerson(contactPerson);
    formrun.close();
}

/// <summary>
/// PaffH 01.09.25
/// </summary>
/// <param name = "_formRun">FormRun</param>
/// <param name = "_set">boolean</param>
/// <param name = "_part">int</param>
protected static void setFilterBVEmail(FormRun _formRun, boolean _set, int _part = 0)
{
    if (formHasMethod(_formRun, identifierStr(setFilterBVEmail)))
    {
        _formRun.setFilterBVEmail(_set, _part);  
    }
}
